gagK(){return"\u062f\u06cc\u0627\u0631\u06d5"},
gage(){return"\u062a\u06d5\u0646\u0647\u0627 \u06a9\u06d5\u06cc\u0633\u06d5\u06a9\u0627\u0646\u06cc \u062e\u06c6\u06cc (\u062f\u06cc\u0632\u0627\u06cc\u0646\u06d5\u0631 \u06cc\u0627\u0646 \u0633\u06cc\u0631\u0627\u0645\u06cc\u0633\u062a \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u06d5 \u062f\u06d5\u0628\u06cc\u0646\u06ce\u062a \u06a9\u06d5 \u062e\u06c6\u06cc \u0648\u06d5\u0631\u06cc\u06af\u0631\u062a\u0648\u0648\u0646\u060c \u0648 \u0647\u06d5\u0631 \u062a\u06d5\u06a9\u0646\u06cc\u0633\u06cc\u0627\u0646\u06ce\u06a9 \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u06d5\u06cc \u0628\u06c6\u06cc \u062f\u06cc\u0627\u0631\u06cc\u06a9\u0631\u0627\u0648\u0646\u061b \u0644\u06d5\u06af\u06d5\u06b5 \u0626\u06d5\u0648 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u06d5\u06cc \u0647\u06ce\u0634\u062a\u0627 \u06a9\u06d5\u0633 \u0648\u06d5\u0631\u06cc\u0646\u06d5\u06af\u0631\u062a\u0648\u0648\u06d5 \u0648 \u0628\u06c6 \u06a9\u06d5\u0633 \u062f\u06cc\u0627\u0631\u06cc\u0646\u06d5\u06a9\u0631\u0627\u0648\u06d5)"},
gagc(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0642\u06c6\u0646\u0627\u063a\u06cc \u06a9\u06d5\u06cc\u0633 \u0628\u06d5\u0631\u06d5\u0648\u067e\u06ce\u0634 \u0628\u0628\u0627\u062a"},
gagb(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0628\u06d5 \u062f\u0648\u06af\u0645\u06d5 \u0642\u06c6\u0646\u0627\u063a \u0628\u06d5\u0631\u06d5\u0648\u067e\u06ce\u0634 \u0628\u0628\u0627\u062a (\u06a9\u0648\u0698\u0627\u0646\u062f\u0646\u06d5\u0648\u06d5 = \u062a\u06d5\u0646\u0647\u0627 \u0628\u06d5 \u0633\u06a9\u0627\u0646\u06cc \u0628\u0627\u0631\u06a9\u06c6\u062f)"},
