gagw(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0646\u0631\u062e \u0648 \u062a\u06ce\u0686\u0648\u0648 \u062f\u06cc\u0627\u0631\u06cc \u0628\u06a9\u0627\u062a/\u0628\u06cc\u06af\u06c6\u0695\u06ce\u062a"},
gagy(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0646\u0631\u062e \u0648 \u062a\u06ce\u0686\u0648\u0648 \u0648 \u0642\u0627\u0632\u0627\u0646\u062c \u0628\u0628\u06cc\u0646\u06ce\u062a \u0644\u06d5 \u06a9\u06d5\u06cc\u0633\u062f\u0627"},
gags(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u0628\u06d5\u0631\u0648\u0627\u0631\u06cc \u0646\u0627\u0631\u062f\u0646\u06cc \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u067e\u06ce\u0634\u062a\u0631 \u0646\u0627\u0631\u062f\u0631\u0627\u0648 \u0695\u0627\u0633\u062a \u0628\u06a9\u0627\u062a\u06d5\u0648\u06d5"},
gagp(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06ce\u06a9 \u0628\u06d5 \u06cc\u06d5\u06a9\u062c\u0627\u0631\u06cc \u0628\u0633\u0695\u06ce\u062a\u06d5\u0648\u06d5 \u0644\u06d5 \u0647\u06d5\u0631 \u0642\u06c6\u0646\u0627\u063a\u06ce\u06a9\u062f\u0627 (\u0628\u06ce \u067e\u0627\u0631\u06d5\u062f\u0627\u0646\u060c \u0647\u06d5\u0631\u06af\u06cc\u0632 \u0646\u06d5\u0646\u06ce\u0631\u062f\u0631\u0627\u0648\u06d5\u060c \u0628\u06d5\u0634\u06ce\u06a9 \u0646\u06cc\u06cc\u06d5 \u0644\u06d5 \u06af\u0631\u0648\u067e\u06ce\u06a9)"},
gagr(){return"\u062f\u06d5\u062a\u0648\u0627\u0646\u06ce\u062a \u06a9\u06d5\u06cc\u0633\u06ce\u06a9\u06cc \u0647\u06d5\u0628\u0648\u0648 \u062f\u06d5\u0633\u062a\u06a9\u0627\u0631\u06cc \u0628\u06a9\u0627\u062a"},
