gIJ(){return"\u062a\u06ce\u0628\u06cc\u0646\u06cc (\u0626\u0627\u0631\u06d5\u0632\u0648\u0648\u0645\u06d5\u0646\u062f\u0627\u0646\u06d5)"},
ga6t(){return"\u067e\u0627\u0631\u06d5\u06cc \u062f\u0631\u0627\u0648 \u062a\u0627 \u0626\u06ce\u0633\u062a\u0627"},
ga6w(){return"\u0645\u0627\u0648\u06d5"},
ga6v(){return"\u062a\u06c6\u0645\u0627\u0631\u06a9\u0631\u062f\u0646\u06cc \u067e\u0627\u0631\u06d5\u062f\u0627\u0646 \u0628\u06c6 \u0626\u06d5\u0645 \u0642\u06d5\u0631\u0632\u06d5"},
