gakd(){return"\u0628\u06c6\u062a\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce"},
gak6(){return"\u0628\u06c6\u062a\u06d5\u06a9\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u06cc\u06ce \u062a\u0627\u06cc\u0628\u06d5\u062a \u0628 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u0627 \u062a\u06d5 \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u06ce\u0646 \u062a\u06d5: \u06a9\u06d5\u06cc\u0633\u0627\u0646 \u062f\u06af\u06d5\u0644 \u0648\u06ce\u0646\u06d5 \u0648 \u0641\u0627\u06cc\u0644\u06ce\u0646 \u0633\u06a9\u0627\u0646\u06ce \u0698 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce \u062f\u0641\u0631\u06ce\u06a9\u06d5\u0646\u060c \u06a9\u06d5\u06cc\u0633 \u062f\u06af\u06d5\u0647\u0646\u06d5 \u062f\u0627\u062e\u0648\u0627\u0632\u06ce\u0646 \u06a9\u06d5\u06cc\u0633\u0627\u0646\u060c \u0648 \u0644 \u0647\u06d5\u0631 \u0642\u0648\u0646\u0627\u063a\u06d5\u06a9\u06ce \u0646\u0627\u0645\u06d5\u06cc\u06d5\u06a9 \u0628\u06c6 \u0648\u0627\u0646 \u062f\u0647\u06ce\u062a. \u06a9\u0627\u0631\u067e\u06ce\u06a9\u0631\u0646\u0627 \u0648\u06cc \u0628\u06ce \u0628\u06d5\u0631\u0627\u0645\u0628\u06d5\u0631\u06d5."},
gLs(){return"\u06af\u0631\u06ce\u062f\u0627\u0646\u0627 \u0628\u06c6\u062a\u06ce \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce"},
gak2(){return"\u0661. \u0644 \u062a\u06d5\u0644\u06d5\u06af\u0631\u0627\u0645\u06ce @BotFather \u06a4\u06d5\u06a9\u06d5 \u0648 \u200e/newbot \u0628\u0641\u0631\u06ce\u06a9\u06d5.\n\u0662. \u0646\u0627\u06a4\u06d5\u06a9\u06ce \u0647\u06d5\u0644\u0628\u0698\u06ce\u0631\u06d5 (\u0628\u06c6 \u0646\u0645\u0648\u0648\u0646\u06d5 \u0646\u0627\u06a4\u06ce \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u0627 \u062a\u06d5) \u0648 \u06cc\u0648\u0632\u06d5\u0631\u0646\u06d5\u06cc\u0645\u06d5\u06a9\u06ce \u0628 bot \u0628 \u062f\u0648\u0648\u0645\u0627\u0647\u06cc\u06a9 \u0628\u0647\u06ce\u062a.\n\u0663. BotFather \u062f\u06ce \u062a\u06c6\u06a9\u0646\u06d5\u06a9\u06ce \u0628\u06c6 \u062a\u06d5 \u0641\u0631\u06ce\u06a9\u06d5\u062a. \u0647\u06d5\u0645\u06cc\u06cc\u06ce \u06a9\u06c6\u067e\u06cc \u0628\u06a9\u06d5 \u0648 \u0644 \u062e\u0648\u0627\u0631\u06ce \u062f\u0627\u0646\u06ce."},
gake(){return"\u062a\u06c6\u06a9\u0646\u0627 \u0628\u06c6\u062a\u06cc"},
gLt(){return"\u0632\u0645\u0627\u0646\u06ce \u0628\u06c6\u062a\u06cc"},
gaka(){return"\u0646\u06cc\u0634\u0627\u0646\u062f\u0627\u0646\u0627 \u0642\u06d5\u0631\u0632\u06ce \u0628\u06c6 \u062f\u06a9\u062a\u06c6\u0631\u0627\u0646"},
gakb(){return"\u062a\u0627\u0628\u0627 \xab\u062d\u0633\u0627\u0628\xbb \u0628\u06c6 \u067e\u06d5\u0695\u06ce\u0646 \u0628\u06c6\u062a\u06cc \u0632\u06ce\u062f\u06d5 \u062f\u06a9\u06d5\u062a\u060c \u06a9\u0648 \u0642\u06d5\u0631\u0632\u06ce \u0645\u0627\u06cc \u06cc\u06ce \u0647\u06d5\u0631 \u062f\u06a9\u062a\u06c6\u0631\u06d5\u06a9\u06cc \u0628\u06c6 \u062a\u0627\u0642\u06cc\u06af\u06d5\u0647\u06ce \u0646\u06cc\u0634\u0627\u0646 \u062f\u062f\u06d5\u062a (\u06a9\u06c6\u06cc\u0627 \u06a9\u06d5\u0634\u0641\u0627 \u062d\u0633\u0627\u0628\u06ce \u062f\u06a9\u062a\u06c6\u0631\u06cc)."},
